sourceDir = '/Users/ccm/Codex/repos/wec-sim-matlab-reference/source';
caseDir = '/tmp/wec-oswec-160-local/applications/Variable_Hydro/paired_Passive_Yaw_irregular_160s_eighth_pruned';
outputDir = '/tmp/wec-oswec-160-local/matlab-oswec-variable-yaw-eighth-160s-audit';
quarterDir = '/tmp/wec-oswec-160-local/matlab-oswec-variable-yaw-160s-audit';
if ~isfolder(outputDir), mkdir(outputDir); end
quarter = readmatrix(fullfile(quarterDir,'quarter_trajectory.csv'));
quarterWave = readmatrix(fullfile(quarterDir,'quarter_wave.csv'));
quarterComponents = readmatrix(fullfile(quarterDir,'components.csv'));
assert(isequal(size(quarter),[64001,7]) && ...
       isequal(size(quarterWave),[64001,2]) && ...
       isequal(size(quarterComponents),[500,4]));
addpath(genpath(sourceDir));
cd(caseDir);
waveFlag = 'irregular';
probeClock = tic;
wecSim;
probeElapsed = toc(probeClock);
assert(strcmp(simu.mode,'normal') && strcmp(simu.solver,'ode4') && ...
       simu.dt == 0.00125 && simu.endTime == 160 && ...
       simu.rampTime == 100 && simu.cicEndTime == 40 && ...
       strcmp(waves.type,'irregular') && waves.phaseSeed == 1 && ...
       isequal(bemDirections,-12:0.25:12));
assert(numel(output.bodies(1).time) == 128001 && ...
       isequal(size(waves.waveAmpTime),[128001,2]));
index = output.bodies(1).hydroForceIndex(:);
assert(all(index>=1 & index<=numel(bemDirections)));
heading = bemDirections(index);
eighth = [output.bodies(1).time(:),output.bodies(1).position(:,6), ...
          output.bodies(1).velocity(:,6),index,heading(:), ...
          output.ptos(1).forceInternalMechanics(:,5), ...
          output.ptos(1).powerInternalMechanics(:,5)];
writematrix(eighth,fullfile(outputDir,'eighth_trajectory.csv'));
writematrix(waves.waveAmpTime,fullfile(outputDir,'eighth_wave.csv'));
components = [waves.omega(:),waves.amplitude(:), ...
              waves.dOmega(:),waves.phase(:)];
writematrix(components,fullfile(outputDir,'components.csv'));
assert(max(abs(eighth(1:2:end,1)-quarter(:,1)))<1e-10);
waveError = max(abs(waves.waveAmpTime(1:2:end,:)-quarterWave),[],'all');
componentError = max(abs(components-quarterComponents),[],'all');
boundaryVisits = nnz(index==1 | index==numel(bemDirections));
metrics = struct('elapsed_seconds',probeElapsed, ...
    'wave_error_m',waveError,'component_error',componentError, ...
    'boundary_visits',boundaryVisits,'heading_min',min(heading), ...
    'heading_max',max(heading));
windows = [120,140,160];
for k=1:numel(windows)
    duration = windows(k);
    nQuarter = round(duration/0.0025)+1;
    nEighth = round(duration/0.00125)+1;
    coarse = quarter(1:nQuarter,:);
    fine = eighth(1:nEighth,:);
    sampled = fine(1:2:end,:);
    coarseWork = -trapz(coarse(:,1),coarse(:,7));
    fineWork = -trapz(fine(:,1),fine(:,7));
    item = struct('duration_s',duration, ...
        'yaw_rad',max(abs(sampled(:,2)-coarse(:,2))), ...
        'yaw_speed_rad_s',max(abs(sampled(:,3)-coarse(:,3))), ...
        'pto_torque_Nm',max(abs(sampled(:,6)-coarse(:,6))), ...
        'relative_pto_work',abs(fineWork-coarseWork)/coarseWork, ...
        'heading_mismatch_samples',nnz(sampled(:,5)~=coarse(:,5)), ...
        'quarter_switches',nnz(diff(coarse(:,5))), ...
        'eighth_switches',nnz(diff(fine(:,5))));
    metrics.windows(k) = item;
end
fid=fopen(fullfile(outputDir,'metrics.json'),'w');
assert(fid~=-1);
fprintf(fid,'%s\n',jsonencode(metrics));
fclose(fid);
fprintf('EIGHTH_PRUNED_160_METRICS %s\n',jsonencode(metrics));
close_system('OSWEC',0);
assert(waveError<1e-12 && componentError<1e-12 && boundaryVisits==0, ...
       'The pruned source run changed the sea or reached the bank edge');
